import { useSdk } from '@cetus/sdk-factory'
import { d } from '@cetus/utils'
import { BinAmount, BinUtils, StrategyType } from 'dd_dlmm_sdk'
import { PriceDataType } from '../create-pool/useCreateDLMMPool'

function useCreatePriceBin() {
  const dlmmSdk = useSdk('dlmm')

  const getDefaultBinPriceAndId = (bin_step: number, active_id: number, decimals_a: number, decimals_b: number) => {
    const lower_bin_id = active_id - 34
    const upper_bin_id = active_id + 34
    const lower_price = BinUtils.getPriceFromBinId(lower_bin_id, bin_step, decimals_a, decimals_b)
    const upper_price = BinUtils.getPriceFromBinId(upper_bin_id, bin_step, decimals_a, decimals_b)
    return {
      lower_bin_id,
      upper_bin_id,
      lower_price,
      upper_price
    }
  }

  const handleActionBinPrice = (price: PriceDataType, bin_step: number, decimals_a: number, decimals_b: number, action: 'Add' | 'Sub' = 'Add') => {
    const active_id = price?.binId

    if (action === 'Sub') {
      const bin_id = active_id - 1
      const price = BinUtils.getPriceFromBinId(bin_id, bin_step, decimals_a, decimals_b)
      return {
        bin_id,
        price
      }
    } else {
      const bin_id = active_id + 1
      const price = BinUtils.getPriceFromBinId(bin_id, bin_step, decimals_a, decimals_b)
      return {
        bin_id,
        price
      }
    }
  }

  const getBinInfosByAutoFill = ({
    input_amount,
    bin_step,
    strategy_type,
    lower_bin_id,
    upper_bin_id,
    fix_amount_a,
    active_id,
    amount_in_active_bin
  }: {
    input_amount: string
    bin_step: number
    active_id: number
    strategy_type: StrategyType
    lower_bin_id: number
    upper_bin_id: number
    fix_amount_a: boolean
    amount_in_active_bin?: BinAmount
  }) => {
    console.log(lower_bin_id, upper_bin_id, 'getBinInfosByAutoFill')
    const bin_infos = dlmmSdk?.Position.calculateAddLiquidityInfo({
      active_id,
      bin_step,
      lower_bin_id,
      upper_bin_id,
      amount_a_in_active_bin: amount_in_active_bin?.amount_a || '0',
      amount_b_in_active_bin: amount_in_active_bin?.amount_b || '0',
      strategy_type,
      coin_amount: input_amount,
      fix_amount_a
    })
    return bin_infos
  }

  const getBinInfosByBothAmount = ({
    amount_a,
    amount_b,
    bin_step,
    strategy_type,
    lower_bin_id,
    upper_bin_id,
    active_id,
    amount_in_active_bin
  }: {
    amount_a: string
    amount_b: string
    bin_step: number
    active_id: number
    strategy_type: StrategyType
    lower_bin_id: number
    upper_bin_id: number
    amount_in_active_bin?: BinAmount
  }) => {
    const bin_infos = dlmmSdk?.Position.calculateAddLiquidityInfo({
      amount_a,
      amount_b,
      active_id,
      bin_step,
      lower_bin_id,
      upper_bin_id,
      amount_a_in_active_bin: amount_in_active_bin?.amount_a || '0',
      amount_b_in_active_bin: amount_in_active_bin?.amount_b || '0',
      strategy_type
    })
    return bin_infos
  }

  const getNumBins = (lower_bin_id: number, upper_bin_id: number) => {
    const gap = upper_bin_id - lower_bin_id
    console.log('getNumBins', gap)
    return d(gap).plus(1).toNumber()
  }

  return { getDefaultBinPriceAndId, handleActionBinPrice, getBinInfosByAutoFill, getBinInfosByBothAmount, getNumBins }
}

export default useCreatePriceBin
