import RangeChartBarPlaceholder from '@/assets/images/dlmm_range_bar_placeholder.png'
import { CurrentBinChartData, MaxBinRangeChartData } from '@/types/dlmm'
import { SingleCoinImage } from '@cetus/ui-kit'
import { addComma, d, formatPercentage } from '@cetus/utils'
import { HStack, Image, Text, VStack } from '@chakra-ui/react'
import Slider from 'rc-slider'
import 'rc-slider/assets/index.css'
import { memo, useCallback, useEffect, useMemo, useState } from 'react'
import { Bar, BarChart, Cell, Tooltip, XAxis, YAxis } from 'recharts'
import CustomBar from './CustomBar'

const LeftColor = '#00D8B6'
const RightColor = '#4A9AEF'

function BinRangeSelectChart(props: {
  activeBin: number
  data: MaxBinRangeChartData
  width: number
  onChangeRange: (min: any, max: any) => void
  height?: number
  noToolTip?: boolean
  isSimple?: boolean
  minBinId?: number
  maxBinId?: number
  currentLiquidityBins?: CurrentBinChartData
}) {
  const { minBinId, maxBinId, height } = props
  // ToLargeData
  const toLargeRange = useMemo(() => {
    if (minBinId !== undefined && maxBinId !== undefined) {
      return d(minBinId).minus(maxBinId).abs().gt(350)
    }
    return false
  }, [minBinId, maxBinId])
  return (
    <div style={{ padding: '0px', width: `${props?.width}px`, height: `${props?.height}px`, margin: '0 auto', position: 'relative' }}>
      {toLargeRange ? (
        <ToLargeData height={height} />
      ) : props?.data?.list?.length > 0 ? (
        <SelectChart {...props} />
      ) : (
        <NoData height={props?.height} />
      )}
    </div>
  )
}

function SelectChart({
  activeBin,
  data,
  width,
  onChangeRange,
  height = 120,
  noToolTip,
  isSimple,
  minBinId,
  maxBinId,
  currentLiquidityBins
}: {
  activeBin: number
  data: MaxBinRangeChartData
  width: number
  onChangeRange: (min: any, max: any) => void
  height?: number
  noToolTip?: boolean
  isSimple?: boolean
  minBinId?: number
  maxBinId?: number
  currentLiquidityBins?: CurrentBinChartData
}) {
  const [range, setRange] = useState<[number, number]>([0, 68])
  const [rangeData, setRangeData] = useState([])
  const maxBinRangeData = data?.list
  const marks = useMemo(() => {
    const unit = parseInt(String(maxBinRangeData?.length / 5))
    const result = maxBinRangeData?.map((item: any, index: number) => {
      if (index % unit === 0 && index !== 0) {
        return item.price
      }
      return ''
    })
    return result
  }, [maxBinRangeData])

  useEffect(() => {
    // const timer = setTimeout(() => {
    const data =
      maxBinRangeData?.map((item: any, index: number) => {
        // 反向时候前面的大于后面的, 所以需要做处理
        if (range[0] <= range[1] ? index < range[0] || index > range[1] : index < range[1] || index > range[0]) {
          return {
            ...item,
            hide: true
          }
        }
        return item
      }) || []

    setRangeData(data)
  }, [range])

  const [hoveredIndex, setHoveredIndex] = useState(null)

  const handleChangeComplete = useCallback(
    (value: any) => {
      const minBin = maxBinRangeData[value[0]].bin_id
      const maxBin = maxBinRangeData[value[1]].bin_id
      if (d(maxBin).gte(minBin)) {
        onChangeRange(minBin, maxBin)
      } else {
        onChangeRange(maxBin, minBin)
      }
    },
    [maxBinRangeData]
  )

  useEffect(() => {
    if (minBinId !== undefined && maxBinId !== undefined && maxBinRangeData && maxBinRangeData?.length > 0) {
      const minIndex = maxBinRangeData.findIndex(item => item.bin_id === minBinId)
      const maxIndex = maxBinRangeData.findIndex(item => item.bin_id === maxBinId)
      setRange([minIndex, maxIndex])
    }
  }, [minBinId, maxBinId, maxBinRangeData])

  const currentLiquidityBinsObj = useMemo(() => {
    if (currentLiquidityBins && currentLiquidityBins?.list?.length > 0) {
      return Object.fromEntries(currentLiquidityBins?.list?.map((item: any) => [item?.bin_id, item]))
    }
    return {}
  }, [currentLiquidityBins])

  const CustomTooltip = useCallback(
    ({ active, payload }: any) => {
      if (!active) return null
      const item = payload?.[0]?.payload

      const currentLiquidityItem = currentLiquidityBinsObj?.[item?.bin_id]
      const yourLiquidityBaseAmountPercent = !Number(currentLiquidityItem?.baseAmount || '0')
        ? '0%'
        : !Number(item?.baseAmount || '0')
          ? '100%'
          : formatPercentage(
              d(currentLiquidityItem?.baseAmount).lt(item?.baseAmount)
                ? d(currentLiquidityItem?.baseAmount).div(item?.baseAmount).mul(100).toString()
                : '100',
              2
            )

      const yourLiquidityQuoteAmountPercent = !Number(currentLiquidityItem?.quoteAmount || '0')
        ? '0%'
        : !Number(item?.quoteAmount || '0')
          ? '100%'
          : formatPercentage(
              d(currentLiquidityItem?.quoteAmount).lt(item?.quoteAmount)
                ? d(currentLiquidityItem?.quoteAmount).div(item?.quoteAmount).toString()
                : '100',
              2
            )

      const isLeft = activeBin <= item?.bin_id
      const isRight = activeBin >= item?.bin_id

      const inPositionHaveLiquidity =
        !!currentLiquidityItem?.newBins && currentLiquidityItem?.newBins?.liquidity && currentLiquidityItem?.newBins?.liquidity !== '0'
      let yourNewLiquidityBasePercent = '0%'
      let yourNewLiquidityQuotePercent = '0%'

      if (inPositionHaveLiquidity) {
        const newInfo = currentLiquidityItem?.newBins
        const amountA = newInfo?.isIncrease
          ? d(currentLiquidityItem?.baseAmount).add(newInfo?.baseAmount).toString()
          : d(currentLiquidityItem?.baseAmount).minus(newInfo?.baseAmount).toString()
        const amountB = newInfo?.isIncrease
          ? d(currentLiquidityItem?.quoteAmount).add(newInfo?.quoteAmount).toString()
          : d(currentLiquidityItem?.quoteAmount).minus(newInfo?.quoteAmount).toString()

        yourNewLiquidityBasePercent = d(amountA).lte(0)
          ? '0%'
          : d(item?.baseAmount).lte(0)
            ? '100%'
            : formatPercentage(d(amountA).div(item?.baseAmount).toString(), 2)
        yourNewLiquidityQuotePercent = d(amountB).lte(0)
          ? '0%'
          : d(item?.quoteAmount).lte(0)
            ? '100%'
            : formatPercentage(d(amountB).div(item?.quoteAmount).toString(), 2)
      }

      return (
        <VStack
          minW="200px"
          bg="#141618"
          borderRadius="12px"
          border="1px solid"
          borderColor="#2A3238"
          padding="8px"
          gap="8px"
          zIndex={90000}
          justify="space-between"
        >
          <HStack justify="space-between" w="100%">
            <Text fontSize="12px" color="text_paragraph">
              Bin Price
            </Text>
            <Text fontSize="12px" color="text_caption">
              {item?.price}
            </Text>
          </HStack>

          {isLeft && (
            <VStack padding="8px 4px" bg="bg_fifth" borderRadius="4px" gap="8px" w="100%">
              <HStack justify="space-between" w="100%">
                <HStack gap="4px">
                  <SingleCoinImage imageUrl={item?.baseLogo} w="16px" h="16px" />
                  <Text fontSize="12px" color="text_paragraph">
                    {item?.baseSymbol}
                  </Text>
                </HStack>
                <Text fontSize="12px" color="text_caption">
                  {addComma(item?.baseAmount)}
                </Text>
              </HStack>
              <HStack justify="space-between" w="100%">
                <Text fontSize="12px" color={item?.bin_id < activeBin ? LeftColor : RightColor}>
                  % Your Liquidity
                </Text>
                <Text fontSize="12px" color="text_caption">
                  {yourLiquidityBaseAmountPercent}
                </Text>
              </HStack>
              {inPositionHaveLiquidity && (
                <HStack justify="space-between" w="100%">
                  <Text fontSize="12px" color={item?.bin_id < activeBin ? LeftColor : RightColor}>
                    % Your New Liquidity
                  </Text>
                  <Text fontSize="12px" color="text_caption">
                    {yourNewLiquidityBasePercent}
                  </Text>
                </HStack>
              )}
            </VStack>
          )}

          {isRight && (
            <VStack padding="8px 4px" bg="bg_fifth" borderRadius="4px" gap="8px" w="100%">
              <HStack justify="space-between" w="100%">
                <HStack gap="4px">
                  <SingleCoinImage imageUrl={item?.quoteLogo} w="16px" h="16px" />
                  <Text fontSize="12px" color="text_paragraph">
                    {item?.quoteSymbol}
                  </Text>
                </HStack>
                <Text fontSize="12px" color="text_caption">
                  {addComma(item?.quoteAmount)}
                </Text>
              </HStack>
              <HStack justify="space-between" w="100%">
                <Text fontSize="12px" color={item?.bin_id > activeBin ? RightColor : LeftColor}>
                  % Your Liquidity
                </Text>
                <Text fontSize="12px" color="text_caption">
                  {yourLiquidityQuoteAmountPercent}
                </Text>
              </HStack>
              {inPositionHaveLiquidity && (
                <HStack justify="space-between" w="100%">
                  <Text fontSize="12px" color={item?.bin_id > activeBin ? RightColor : LeftColor}>
                    % Your New Liquidity
                  </Text>
                  <Text fontSize="12px" color="text_caption">
                    {yourNewLiquidityQuotePercent}
                  </Text>
                </HStack>
              )}
            </VStack>
          )}
        </VStack>
      )
    },
    [currentLiquidityBinsObj, activeBin]
  )

  return !isSimple ? (
    <div style={{ padding: '0px', width: `${width}px`, height: `${height}px`, margin: '0 auto', position: 'relative', zIndex: 100 }}>
      <style>{`
        .rc-slider-handle:after {
          content: '';
          width: 2px;
          height: 6px;
          background: #fff;
          position: absolute;
          left: 4px;
          top: 3px;
        }
        .rc-slider-handle-dragging.rc-slider-handle-dragging.rc-slider-handle-dragging {
          box-shadow: none;
          border-color: #fff!important;
        }
        .recharts-tooltip-wrapper {
          z-index: 9999 !important; /* 确保高于遮挡元素 */
        }
          
      `}</style>
      {/* 下方灰色柱状图 */}
      <div style={{ position: 'absolute', left: 0, right: 0, top: 0, bottom: 0 }}>
        <BarChart
          width={width}
          height={height}
          data={maxBinRangeData}
          margin={{ top: 10, right: 0, left: 0, bottom: 0 }}
          barCategoryGap={0}
          barGap={0}
        >
          <XAxis dataKey="price" hide={true} />
          <YAxis hide={true} />
          <Bar dataKey="liquidity" barSize={20} fill="#222C35" animationDuration={0} shape={<CustomBar />} />
        </BarChart>
      </div>

      {/* 选中区间动画柱状图 */}
      <div style={{ position: 'absolute', left: 0, right: 0, top: 0, bottom: 0, pointerEvents: 'auto' }}>
        {/* <BarChart width={width} height={height} data={rangeData} margin={{ top: 10, right: 0, left: 0, bottom: 0 }} barCategoryGap={0} barGap={0}> */}
        <BarChart width={width} height={height} data={rangeData} margin={{ top: 10, right: 0, left: 0, bottom: 0 }} barCategoryGap={0} barGap={0}>
          <XAxis dataKey="price" hide={true} />
          <YAxis hide={true} />

          <Bar
            dataKey="liquidity"
            barSize={20}
            fill="#354F62"
            shape={<CustomBar />}
            isAnimationActive={true}
            // 动画持续时间（单位：毫秒，默认300ms）
            animationDuration={800}
            // 动画缓动函数（可选：ease-in, ease-out, ease-in-out等）
            animationEasing="ease-in-out"
          >
            {rangeData.map((entry, index) => {
              // 根据liquidity值选择颜色或渐变
              const fill = entry?.hide ? 'rgba(0,0,0,0)' : '#354F62'

              return <Cell key={`cell-${index}`} fill={fill} />
            })}
          </Bar>

          {/* 顶层柱状图：动态动画，选中区间高亮 */}
          {/* <Bar dataKey="animatedValue" barSize={-20} animationDuration={0} fill="red"></Bar> */}
        </BarChart>
      </div>

      {/* 标识当前bin和为了tooltip做的透明柱状图*/}
      <div style={{ position: 'absolute', left: 0, right: 0, top: 0, bottom: 0 }}>
        <BarChart
          width={width}
          height={height}
          data={maxBinRangeData}
          margin={{ top: 10, right: 0, left: 0, bottom: 0 }}
          barCategoryGap={0}
          barGap={0}
          onMouseLeave={() => setHoveredIndex(null)}
        >
          <XAxis dataKey="price" hide={true} />
          <YAxis hide={true} />
          {!noToolTip && (
            <Tooltip
              cursor={false} // 禁用全屏竖线背景
              content={<CustomTooltip />}
            />
          )}

          <Bar
            dataKey="liquidity"
            shape={<CanHoverCustomBar height={height} hoveredIndex={hoveredIndex} activeBin={activeBin} setHoveredIndex={setHoveredIndex} />}
          >
            {maxBinRangeData.map((entry: any, index: number) => {
              // 根据liquidity值选择颜色或渐变
              const fill =
                !noToolTip && index === hoveredIndex
                  ? '#76C8FF'
                  : entry.bin_id === activeBin
                    ? '#568BB0' // 引用渐变
                    : 'rgba(0,0,0,0)'

              return <Cell key={`cell-${index}`} fill={fill} />
            })}
          </Bar>
        </BarChart>
      </div>

      {/* 双边滑动杆 */}
      <div style={{ width: '100%', position: 'absolute', left: 0, bottom: '-9px' }}>
        <Slider
          range
          min={0}
          max={maxBinRangeData.length - 1}
          value={range}
          onChange={newRange => setRange(newRange as [number, number])} // 更新选中区间
          onChangeComplete={handleChangeComplete} // 更新选中区间
          marks={marks}
          step={1}
          dots={false}
          dotStyle={{ display: 'none' }}
          handleStyle={[
            {
              // 左侧滑块样式
              borderColor: '#00D8B6', // 蓝色边框
              backgroundColor: '#00D8B6',
              borderRadius: '4px 2px 2px 4px',
              width: 14,
              height: 16,
              opacity: 1,
              top: '4px',
              zIndex: 100
            },
            {
              // 右侧滑块样式
              borderColor: '#4A9AEF', // 蓝色边框
              backgroundColor: '#4A9AEF',
              borderRadius: '2px 4px 4px 2px',
              width: 14,
              height: 16,
              opacity: 1,
              top: '4px',
              zIndex: 100
            }
          ]}
          trackStyle={[
            {
              backgroundColor: '#568BB0', // 选中轨道颜色（默认蓝色）
              height: 4, // 轨道高度
              borderRadius: 0 // 轨道圆角
            }
          ]}
          railStyle={{
            backgroundColor: '#222C35', // 外部轨道颜色（默认浅灰色）
            height: 4, // 轨道高度
            borderRadius: 0 // 轨道圆角
          }}
        />
      </div>
    </div>
  ) : (
    <div style={{ padding: '0px', width: `${width}px`, height: `${height}px`, margin: '0 auto', position: 'relative' }}>
      <div style={{ position: 'absolute', left: 0, right: 0, top: 0, bottom: 0 }}>
        <BarChart
          width={width}
          height={height}
          data={maxBinRangeData}
          margin={{ top: 10, right: 0, left: 0, bottom: 0 }}
          barCategoryGap={0}
          barGap={0}
        >
          <XAxis dataKey="price" tickSize={0} tickMargin={10} tick={{ fontSize: '12px', fill: '#909CA4' }} />
          <YAxis hide={true} />
          {!noToolTip && (
            <Tooltip
              cursor={false} // 禁用全屏竖线背景
              content={<CustomTooltip />}
            />
          )}

          <Bar dataKey="liquidity" onMouseEnter={(e, index) => setHoveredIndex(index)} onMouseLeave={() => setHoveredIndex(null)}>
            {maxBinRangeData.map((entry: any, index: number) => {
              // 根据liquidity值选择颜色或渐变
              const fill =
                !noToolTip && index === hoveredIndex
                  ? '#76C8FF'
                  : entry.bin_id === activeBin
                    ? '#568BB0' // 引用渐变
                    : '#222C35'

              return <Cell key={`cell-${index}`} fill={fill} />
            })}
          </Bar>
        </BarChart>
      </div>
    </div>
  )
}

const CanHoverCustomBar = (props: any) => {
  const { fill, x, y, width, height: barHeight, index, height: chartHeight, hoveredIndex, activeBin, payload, setHoveredIndex } = props

  // 计算柱子实际高度（可能为0）
  const actualBarHeight = Math.max(0, barHeight)

  // 判断是否高亮
  const isHovered = index === hoveredIndex
  const isActive = payload?.bin_id === activeBin

  // 顶部圆角半径
  const radius = 3

  return (
    <g>
      {/* 1. 实际柱子部分 */}
      <path
        d={`
          M${x},${y + actualBarHeight}
          L${x},${y + radius}
          Q${x},${y} ${x + radius},${y}
          L${x + width - radius},${y}
          Q${x + width},${y} ${x + width},${y + radius}
          L${x + width},${y + actualBarHeight}
          Z
        `}
        fill={fill}
      />

      {/* 2. 透明覆盖层 - 覆盖整个柱子区域 */}
      <rect
        x={x}
        y={0} // 从顶部开始
        width={width}
        height={chartHeight} // 覆盖整个图表高度
        fill="transparent"
        onMouseEnter={() => setHoveredIndex(index)}
        style={{ cursor: 'pointer' }}
      />

      {/* 3. 高亮边框效果（可选） */}
      {/* {isHovered && (
        <path
          d={`
            M${x},${y + actualBarHeight}
            L${x},${y + radius}
            Q${x},${y} ${x + radius},${y}
            L${x + width - radius},${y}
            Q${x + width},${y} ${x + width},${y + radius}
            L${x + width},${y + actualBarHeight}
            Z
          `}
          fill="none"
          stroke="#76C8FF"
          strokeWidth={2}
        />
      )} */}
    </g>
  )
}

const NoData = ({ height }: { height: number }) => {
  return (
    <VStack w="100%" gap="0px">
      <Image src={RangeChartBarPlaceholder} w="100%" h={`${height - 24}px`} />
      <Text fontSize="12px" color="text_paragraph" mt="16px">
        Loading ...
      </Text>
    </VStack>
  )
}

const ToLargeData = ({ height }: { height: number }) => {
  return (
    <VStack w="100%" gap="0px">
      <Image src={RangeChartBarPlaceholder} w="100%" h={`${height - 24}px`} />
      <Text fontSize="12px" color="text_paragraph" mt="16px">
        Missing chart data
      </Text>
    </VStack>
  )
}

export default memo(BinRangeSelectChart)
