import ActionButton from '@/components/liquidity/common/ActionButton'
import { RangePriceType } from '@/store/dlmm/addDlmmLiquidity'
import { InputBox } from '@cetus/design'
import { d, removeComma } from '@cetus/utils'
import { HStack, Input, Skeleton, Text, VStack } from '@chakra-ui/react'
import { useCallback, useEffect, useState } from 'react'

export default function PriceInput({
  title,
  perText,
  data,
  direct,
  loading,
  handleAddPrice,
  handleSubPrice,
  onPriceChange,
  minPrice = '0',
  maxPrice = '∞'
}: {
  title: string
  perText: string
  data: RangePriceType
  direct: boolean
  loading?: boolean
  handleAddPrice: (price: RangePriceType) => void
  handleSubPrice: (price: RangePriceType) => void
  onPriceChange: (currentPrice: RangePriceType, value: string) => void
  minPrice?: string
  maxPrice?: string
}) {
  const [inputValue, setInputValue] = useState('')

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value
    if (value && value.startsWith('-')) {
      return
    }
    if (isAllowed(value) || isAllowed(value.split(',').join(''))) {
      setInputValue(value)
    }
  }

  useEffect(() => {
    if (!data || !data.price) return

    console.log('🚀🚀🚀 ~ PriceInput.tsx:45 ~ useEffect ~ data:', data)
    const value = direct ? data.displayPrice : data.displayReversePrice
    console.log('🚀🚀🚀 ~ PriceInput.tsx:42 ~ useEffect ~ value:', value)
    setInputValue((value as string) || '')
  }, [data?.price, direct])

  const handleAdd = useCallback(() => {
    direct ? handleAddPrice(data) : handleSubPrice(data)
  }, [direct, data?.price])

  const handleSub = useCallback(() => {
    direct ? handleSubPrice(data) : handleAddPrice(data)
  }, [direct, data?.price])

  const handleOnBlur = useCallback(() => {
    let value
    if (!inputValue) {
      value = (data?.displayPrice as string) || ''
      setInputValue(value)
      return
    }
    try {
      onPriceChange(data, direct ? inputValue : d(1).div(inputValue).toString())
    } catch (error) {
      onPriceChange(data, inputValue)
    }
  }, [inputValue, data, direct])

  const isAllowed = (value: string) => {
    // 允许空字符串、数字、小数或∞
    return value === '' || /^-?\d*\.?\d*$/.test(value) || value === '∞'
  }
  return (
    <InputBox borderRadius="12px" p="12px">
      <HStack flex="1" justify="space-between">
        <ActionButton type="Sub" onClick={handleSub} disabled={minPrice !== '∞' ? d(removeComma(inputValue)).lte(minPrice) : inputValue === '∞'} />
        <VStack>
          <Text fontSize="12px" color="primary_gray">
            {title}
          </Text>
          {loading ? (
            <Skeleton w="100px" h="14px" />
          ) : (
            <Input
              value={inputValue}
              onChange={handleChange}
              placeholder="0.0"
              style={{
                width: 'calc(100% - 8px)',
                background: 'none',
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                opacity: 1,
                outline: 'none',
                color: 'var(--chakra-colors-text_caption)',
                fontSize: '14px',
                height: '14px',
                lineHeight: '14px',
                textAlign: 'center',
                fontWeight: '500'
              }}
              onBlur={handleOnBlur}
            />
          )}

          <Text fontSize="12px" color="primary_gray">
            {perText}
          </Text>
        </VStack>

        <ActionButton type="Add" onClick={handleAdd} disabled={maxPrice !== '∞' ? d(removeComma(inputValue)).gte(maxPrice) : inputValue === '∞'} />
      </HStack>
    </InputBox>
  )
}
