import { ChartBinItem, CurrentBinChartData } from '@/types/dlmm'
import { addComma, d } from '@cetus/utils'
import { Box, HStack, Text, VStack } from '@chakra-ui/react'
import { memo, useCallback, useMemo, useState } from 'react'
import { Bar, BarChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import CustomBar from './CustomBar'

const LeftColor = '#00D8B6'
const RightColor = '#4A9AEF'

const LeftColorOpacity = 'rgba(0,216,182,0.2)'
const RightColorOpacity = 'rgba(59,130,246,0.2)'

// 获取柱子颜色
function getBinBarColor(info: ChartBinItem, activeBin: number, direct: boolean, isOpacity?: boolean) {
  if (info?.bin_id == activeBin && d(info.amount_a).gt(0)) {
    return isOpacity ? 'url(#splitGradientOpacity)' : 'url(#splitGradient)'
  }

  if (d(info?.bin_id).lte(activeBin)) {
    return isOpacity ? LeftColorOpacity : LeftColor
  }

  if (d(info?.bin_id).gte(activeBin)) {
    return isOpacity ? RightColorOpacity : RightColor
  }

  return isOpacity ? RightColorOpacity : RightColor
}

const getNewBin = (payload: any, height: number) => {
  const newBinRate = payload?.newBins?.liquidity ? d(payload?.newBins?.liquidity).div(payload?.totalLiquidity).toString() : '0'
  const newBinHeight = d(height).mul(newBinRate).toNumber()
  return newBinHeight
}

const ActiveBinBar = (props: any) => {
  const { payload, x, y, height, width, isOpacity, radius } = props
  const aHeight = d(height).mul(payload.quantityA).toNumber()
  const bHeight = d(height).minus(aHeight).toNumber()

  return (
    <g>
      <CustomBar x={x} y={y} width={width} height={aHeight} radius={radius} fill={isOpacity ? LeftColorOpacity : LeftColor} />
      <CustomBar x={x} y={y + aHeight} width={width} height={bHeight} radius={0} fill={isOpacity ? RightColorOpacity : RightColor} />
    </g>
  )
}

const BarItem = (props: any) => {
  const { payload, x, y, height, width, isOpacity, activeBin } = props
  return payload?.quantityA !== undefined && payload?.bin_id == activeBin ? <ActiveBinBar {...props} /> : <CustomBar {...props} />
}

const renderCustomBar = (props: any, activeBin: number, direct: boolean, height: number, fromPosition?: boolean) => {
  const [hoveredIndex, setHoveredIndex] = useState(null)
  const { x, y, width, payload, index } = props
  const customHeight = props.height
  const isHovered = index === hoveredIndex

  let newBinHeight = 0
  if (fromPosition && payload?.newBins?.liquidity) {
    newBinHeight = getNewBin(payload, customHeight)
  }

  let otherHeight = 0
  if (fromPosition) {
    otherHeight = d(customHeight).minus(newBinHeight).toNumber()
  }

  const radius = payload?.noRadius || !payload?.liquidity ? 0 : 2
  return (
    <g onMouseEnter={() => setHoveredIndex(index)} onMouseLeave={() => setHoveredIndex(null)}>
      {!fromPosition ? (
        <BarItem
          x={x}
          y={y}
          width={width}
          height={customHeight}
          radius={radius}
          fill={getBinBarColor(payload, activeBin, direct)}
          activeBin={activeBin}
          payload={payload}
        />
      ) : (
        <g>
          <BarItem
            x={x}
            y={y}
            width={width}
            height={newBinHeight}
            radius={radius}
            fill={getBinBarColor(payload, activeBin, direct, true)}
            activeBin={activeBin}
            payload={payload.newBins}
            isOpacity={true}
          />
          <BarItem
            x={x}
            y={y + newBinHeight}
            width={width}
            height={otherHeight}
            radius={radius}
            fill={getBinBarColor(payload, activeBin, direct)}
            activeBin={activeBin}
            payload={payload}
          />
        </g>
      )}
      {isHovered && <rect x={x} y={y} width={width} height={customHeight} fill="rgba(0,0,0,0.3)" />}
      {payload.bin_id == activeBin && (
        <g>
          {/* 竖线 */}
          <line x1={x + width / 2} y1={0} x2={x + width / 2} y2={height - 30} stroke="#fff" strokeWidth={2} />
          {/* 倒三角 */}
          <path d={`M${x + width / 2 - 5},${0} L${x + width / 2},${6} L${x + width / 2 + 5},${0} Z`} fill="#fff" />
        </g>
      )}
    </g>
  )
}

function CurrentLiquidityChart({
  width,
  data,
  activeBin,
  height = 192,
  fromPosition,
  type = 'position',
  direct = true
}: {
  width: number
  data: CurrentBinChartData
  activeBin: number
  height?: number
  fromPosition?: boolean
  type?: 'position' | 'pool' | 'simulation'
  direct?: boolean
}) {
  const toLargeRange = useMemo(() => {
    return !!data?.toLarge
  }, [data?.toLarge])

  const CustomTooltip = useCallback(
    ({ active, payload }: any) => {
      if (!active || !payload?.[0]?.payload) return null

      const item = payload[0].payload
      const isLeft = activeBin <= item.bin_id
      const isRight = activeBin >= item.bin_id
      const hasLiquidityChange = !!item.newBins?.liquidity && item.newBins.liquidity !== '0'
      const posAction = item.newBins?.isIncrease ? 'Add' : 'Remove'

      const renderRow = (label: string, value: string, color?: string, showAddRemove = false) => (
        <HStack w="100%" justify="space-between">
          <HStack gap="4px">
            {color && <ColorBlock color={color} />}
            <Text fontSize="12px" color="text_paragraph">
              {label}
              {showAddRemove ? ` (${posAction})` : ''}
            </Text>
          </HStack>
          <Text fontSize="12px" color="text_caption">
            {addComma(value)}
          </Text>
        </HStack>
      )

      return (
        <VStack minW="200px" bg="#141618" borderRadius="6px" border="1px solid" borderColor="#2A3238" padding="12px" gap="12px">
          {renderRow('Bin Price', item.price)}

          {isLeft && renderRow(item.baseSymbol, item.baseAmount, item.bin_id < activeBin ? LeftColor : RightColor)}

          {isLeft &&
            hasLiquidityChange &&
            renderRow(item.baseSymbol, item.newBins.baseAmount || '0', item.bin_id < activeBin ? LeftColorOpacity : RightColorOpacity, true)}

          {isRight && renderRow(item.quoteSymbol, item.quoteAmount, item.bin_id > activeBin ? RightColor : LeftColor)}

          {isRight &&
            hasLiquidityChange &&
            renderRow(item.quoteSymbol, item.newBins.quoteAmount || '0', item.bin_id > activeBin ? RightColorOpacity : LeftColorOpacity, true)}
        </VStack>
      )
    },
    [activeBin]
  )

  return (
    <VStack gap="0px" p="0px" width={width} height={height} position="relative">
      {!!data && data?.list?.length > 0 ? (
        toLargeRange ? (
          <ToLargeData />
        ) : (
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={data?.list} margin={{ top: 8, right: 0, left: 0, bottom: 0 }}>
              {/* 定义渐变 */}
              <defs>
                <linearGradient id="splitGradient" x1="0%" y1="100%" x2="0%" y2="0%">
                  <stop offset="50%" stopColor={direct ? LeftColor : RightColor} />
                  <stop offset="50%" stopColor={direct ? RightColor : LeftColor} />
                </linearGradient>
              </defs>
              <defs>
                <linearGradient id="splitGradientOpacity" x1="0%" y1="100%" x2="0%" y2="0%">
                  <stop offset="50%" stopColor={direct ? LeftColorOpacity : RightColorOpacity} />
                  <stop offset="50%" stopColor={direct ? RightColorOpacity : LeftColorOpacity} />
                </linearGradient>
              </defs>
              {/* <CartesianGrid strokeDasharray="3 3" /> */}
              <XAxis dataKey="price" tickLine={false} tick={{ fontSize: '12px', fill: '#909CA4' }} />
              <YAxis type="number" domain={[0, data?.max]} hide={true} />
              <Tooltip cursor={false} content={<CustomTooltip />} />
              {/* <Legend /> */}
              {/* <Bar dataKey="liquidity">
            {data.map((entry, index) => {
              // 根据liquidity值选择颜色或渐变
              const fill =
                entry.bin === activeBin
                  ? 'url(#splitGradient)' // 引用渐变
                  : entry.bin < activeBin
                    ? LeftColor
                    : RightColor

              return <Cell key={`cell-${index}`} fill={fill}></Cell>
            })}
          </Bar> */}
              <Bar
                dataKey={fromPosition ? 'totalLiquidity' : 'liquidity'}
                shape={(props: any) => renderCustomBar(props, activeBin, direct!, height, fromPosition)}
              />
              {/* <Bar dataKey={fromPosition ? 'totalLiquidity' : 'liquidity'} /> */}
            </BarChart>
          </ResponsiveContainer>
        )
      ) : (
        <NoData type={type} />
      )}
    </VStack>
  )
}

const ColorBlock = ({ color }: { color: string }) => {
  return <Box w="12px" h="12px" bg={color} borderRadius="4px" />
}

const NoData = ({ type = 'simulation' }: { type?: 'pool' | 'position' | 'simulation' }) => {
  return (
    <VStack
      w="100%"
      h="100%"
      gap="8px"
      bg="center / contain no-repeat url('/images/dlmm_liquidity_bg.png') rgba(129,133,139,0.04)"
      alignItems="center"
      justify="center"
      position="absolute"
      left="0px"
      top="0px"
      backdropFilter="blur(2px)"
      borderRadius="12px"
    >
      <Text color="text_caption" fontSize="14px">
        Preview your liquidity position
      </Text>
      <Text color="text_paragraph" fontSize="12px">
        Please enter deposit amount and select price range
      </Text>
    </VStack>
  )
}

const ToLargeData = () => {
  return (
    <VStack
      w="100%"
      h="100%"
      gap="8px"
      bg="center / contain no-repeat url('/images/dlmm_liquidity_bg.png') rgba(129,133,139,0.04)"
      alignItems="center"
      justify="center"
      position="absolute"
      left="0px"
      top="0px"
      backdropFilter="blur(2px)"
      borderRadius="12px"
    >
      <Text color="text_caption" fontSize="14px">
        Missing chart data
      </Text>
      <Text color="text_paragraph" fontSize="12px">
        Chart cannot be generated for this price range
      </Text>
    </VStack>
  )
}

export default memo(CurrentLiquidityChart)
