import useDlmmLiquidityStore from '@/store/dlmm'
import { CetusTooltip } from '@cetus/design'
import { HStack, Image, Stack, StackProps, Text } from '@chakra-ui/react'
import { StrategyType } from 'dd_dlmm_sdk'

function SelectStrategy() {
  const { strategy, setStrategy } = useDlmmLiquidityStore()
  return (
    <HStack justify="space-between" gap="16px">
      <Strategy size="m" type={StrategyType.Spot} isActive={strategy === StrategyType.Spot} onClick={() => setStrategy(StrategyType.Spot)} />
      <Strategy size="m" type={StrategyType.Curve} isActive={strategy === StrategyType.Curve} onClick={() => setStrategy(StrategyType.Curve)} />
      <Strategy size="m" type={StrategyType.BidAsk} isActive={strategy === StrategyType.BidAsk} onClick={() => setStrategy(StrategyType.BidAsk)} />
    </HStack>
  )
}

type StrategyProps = {
  isActive: boolean
  onClick: (type: StrategyType) => void
  type: StrategyType
  size?: 's' | 'm' | 'l'
}

const strategyMap = {
  [StrategyType.Spot]: {
    title: 'Spot',
    icon: '/images/strategy/spot_active.png',
    tooltip: 'Evenly distributes liquidity across the selected price range, providing uniform coverage throughout the range.'
  },
  [StrategyType.Curve]: {
    title: 'Curve',
    icon: '/images/strategy/curve_active.png',
    tooltip: 'Concentrates liquidity near the current price, gradually decreasing toward both ends of the selected range.'
  },
  [StrategyType.BidAsk]: {
    title: 'Bid-Ask',
    icon: '/images/strategy/bidask_active.png',
    tooltip: 'Allocates liquidity in an inverse curve distribution to capture volatility of bid-ask spread.'
  }
}

const styleMap: Record<'s' | 'm' | 'l', StackProps> = {
  s: {
    flexDir: 'row',
    borderRadius: '8px',
    gap: '8px',
    p: '12px 12px'
  },
  m: {
    flexDir: 'column-reverse',
    borderRadius: '8px',
    p: '12px 32px',
    gap: '8px'
  },
  l: {
    flexDir: 'column-reverse',
    borderRadius: '12px',
    gap: '8px',
    p: '12px 44px'
  }
}

const sizeMap = {
  s: {
    w: '60px',
    h: '24px'
  },
  m: {
    w: '80px',
    h: '32px'
  },
  l: {
    w: '80px',
    h: '32px'
  }
}

export const Strategy = ({ isActive, onClick, type, size = 's' }: StrategyProps) => {
  const { title, icon, tooltip } = strategyMap[type]

  const style = styleMap[size]

  const { w, h } = sizeMap[size]

  return (
    <CetusTooltip
      tooltip={
        <Text fontSize="12px" lineHeight="20px">
          {tooltip}
        </Text>
      }
    >
      <Stack
        bg={isActive ? 'primary_opacity.10' : ''}
        {...style}
        alignItems="center"
        onClick={() => onClick(type)}
        cursor="pointer"
        border="1px solid"
        borderColor={!isActive ? 'border' : 'transparent'}
      >
        <Text fontWeight={isActive ? '500' : '400'} color={isActive ? 'primary' : 'text_paragraph'}>
          {title}
        </Text>
        <Image src={icon} w={w} h={h} opacity={isActive ? 1 : 0.5} />
      </Stack>
    </CetusTooltip>
  )
}

export default SelectStrategy
